import{_ as e,o as a,c as n,a0 as s}from"./chunks/framework.DzvPB4Y-.js";const m=JSON.parse('{"title":"Choose a Framework by Business Scenario","description":"","frontmatter":{},"headers":[],"relativePath":"frameworks/index.md","filePath":"frameworks/index.md"}'),i={name:"frameworks/index.md"};function r(o,t,d,l,c,u){return a(),n("div",null,[...t[0]||(t[0]=[s('<h1 id="choose-a-framework-by-business-scenario" tabindex="-1">Choose a Framework by Business Scenario <a class="header-anchor" href="#choose-a-framework-by-business-scenario" aria-label="Permalink to &quot;Choose a Framework by Business Scenario&quot;">​</a></h1><p>Business frameworks combine reusable domain models, constraints, candidate generation and solving workflows. You supply business data, choose objectives and connect a solver instead of rebuilding every decision variable and constraint.</p><p>This path runs alongside <a href="/ospf/guide/getting-started.html">modeling with Core</a>: reuse a suitable framework first; combine business frameworks or build a custom model with Core when your requirements exceed its scope. DDD and column-generation theory are not prerequisites for the first lesson.</p><h2 id="which-framework-fits-my-problem" tabindex="-1">Which Framework Fits My Problem? <a class="header-anchor" href="#which-framework-fits-my-problem" aria-label="Permalink to &quot;Which Framework Fits My Problem?&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Your decision</th><th>Framework</th><th>First lesson</th></tr></thead><tbody><tr><td>Pack existing long items into length-limited containers (cut-to-length profile loading)</td><td><a href="./bpp1d/">1D packing · BPP1D</a></td><td><a href="./bpp1d/first-packing.html">Your First 1D Packing: Items, spacing and container inventory</a></td></tr><tr><td>Place existing 2D items on finite sheets (pallet loading)</td><td><a href="./bpp2d/">2D packing · BPP2D</a></td><td><a href="./bpp2d/first-layout.html">Your First 2D Layout: Rectangle layouts and validation</a></td></tr><tr><td>Load cargo into boxes or shipping containers (container consolidation)</td><td><a href="./bpp3d/">3D packing · BPP3D</a></td><td><a href="./bpp3d/first-loading.html">Your First 3D Loading: Start with cuboid cargo</a></td></tr><tr><td>Slit material to satisfy orders of different widths (steel/film slitting)</td><td><a href="./csp1d/">1D cutting · CSP1D</a></td><td><a href="./csp1d/first-slitting.html">Your First Slitting Plan: Product demand and cutting plans</a></td></tr><tr><td>Cut rectangular products from sheets or coils (sheet/glass cutting)</td><td><a href="./csp2d/">2D cutting · CSP2D</a></td><td><a href="./csp2d/first-cutting.html">Your First Cutting Plan: Materials, patterns and production counts</a></td></tr><tr><td>Schedule activities jointly using time and resources (APS machine scheduling)</td><td><a href="./gantt/">Time and resources · Gantt</a></td><td><a href="./gantt/first-schedule.html">Your First Activity Schedule: Finite-candidate activity scheduling</a></td></tr><tr><td>Configure supply, flow, paths and network construction (supply-chain allocation)</td><td><a href="./network/">Network optimization</a></td><td><a href="./network/first-flow.html">Your First Network Flow: Start with a small flow problem</a></td></tr></tbody></table><h2 id="two-important-distinctions" tabindex="-1">Two Important Distinctions <a class="header-anchor" href="#two-important-distinctions" aria-label="Permalink to &quot;Two Important Distinctions&quot;">​</a></h2><h3 id="packing-versus-cutting-business-semantics-not-just-dimensions" tabindex="-1">Packing Versus Cutting: Business Semantics, Not Just Dimensions <a class="header-anchor" href="#packing-versus-cutting-business-semantics-not-just-dimensions" aria-label="Permalink to &quot;Packing Versus Cutting: Business Semantics, Not Just Dimensions&quot;">​</a></h3><ul><li><strong>Choose CSP for pattern reuse, production quantities and overproduction rules:</strong> focus on material processing, demand and manufacturing constraints.</li><li><strong>Choose BPP for container assignment, coordinates and orientation:</strong> focus on placing existing items.</li><li>Check business semantics: BPP2D includes spacing, kerf and remnants; fixed-sheet CSP2D also has a packing structure. Kerf alone does not determine the choice.</li></ul><h3 id="gantt-versus-network-compose-when-necessary" tabindex="-1">Gantt Versus Network: Compose When Necessary <a class="header-anchor" href="#gantt-versus-network-compose-when-necessary" aria-label="Permalink to &quot;Gantt Versus Network: Compose When Necessary&quot;">​</a></h3><ul><li><strong>Choose Gantt for activity timing and resource occupancy:</strong> activities, dependencies and calendars.</li><li><strong>Choose Network for flow, paths and network construction:</strong> topology, resource paths and structural decisions.</li><li>Combine when needed: a maintenance schedule can use a Network routing subproblem. Vehicle routing is an advanced Network topic.</li></ul><h2 id="recommended-learning-path" tabindex="-1">Recommended Learning Path <a class="header-anchor" href="#recommended-learning-path" aria-label="Permalink to &quot;Recommended Learning Path&quot;">​</a></h2><ol><li>Read <a href="./setup.html">environment and running examples</a>. Add domain dependencies and choose a real backend or the documented default heuristic.</li><li>Select a framework and inspect its inputs, outputs and exclusions.</li><li>Use the first-lesson example function and launcher in a small application to construct input, call the framework and read results.</li><li>Make the business change at the end and update the corresponding acceptance checks.</li><li>Read <a href="./integration.html">Integrate Your Business</a>, then follow the framework&#39;s second lesson to replace demand, objectives and rules with your own data.</li><li>Continue to <a href="/ospf/examples/framework-examples.html">integrated examples</a> or <a href="/ospf/guide/use-ddd-architecture.html">DDD architecture</a> for cross-domain composition.</li></ol><h2 id="what-comes-after-the-first-run" tabindex="-1">What Comes After the First Run? <a class="header-anchor" href="#what-comes-after-the-first-run" aria-label="Permalink to &quot;What Comes After the First Run?&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Framework</th><th>Second lesson</th><th>Question to answer</th></tr></thead><tbody><tr><td>1D packing · BPP1D</td><td><a href="./bpp1d/business-scenario.html">Container types, stock and cost</a></td><td>Why do minimum count and minimum cost choose different types?</td></tr><tr><td>2D packing · BPP2D</td><td><a href="./bpp2d/business-scenario.html">Sheet types, rotation and spacing</a></td><td>Why can adequate area still fail to fit?</td></tr><tr><td>3D packing · BPP3D</td><td><a href="./bpp3d/business-scenario.html">Bin types and objectives</a></td><td>How do volume defaults interact with business cost?</td></tr><tr><td>1D cutting · CSP1D</td><td><a href="./csp1d/business-scenario.html">Demand units and business rules</a></td><td>How do rolls, mass and plan usage relate?</td></tr><tr><td>2D cutting · CSP2D</td><td><a href="./csp2d/business-scenario.html">Kerf, cutting process and coils</a></td><td>Why is geometric fit insufficient for manufacturing?</td></tr><tr><td>Time and resources · Gantt</td><td><a href="./gantt/business-scenario.html">Calendars and rolling recovery</a></td><td>How do facts, frozen choices and adjustable baselines differ?</td></tr><tr><td>Network optimization</td><td><a href="./network/business-scenario.html">Shared resources, shortage and embedding</a></td><td>Why can adequate arc capacity still fail to deliver?</td></tr></tbody></table><p>Second lessons provide scenario inputs and business-rule examples, and identify the parts your application must implement. Use hand calculations as business references and interpret the solving scope from the returned reports.</p><h2 id="what-counts-as-understanding-the-result" tabindex="-1">What Counts as Understanding the Result? <a class="header-anchor" href="#what-counts-as-understanding-the-result" aria-label="Permalink to &quot;What Counts as Understanding the Result?&quot;">​</a></h2><p>Success is not just a successful function return. Explain the quantities and units, hard rules, objective, demand satisfaction and scope of the evidence.</p><table tabindex="0"><thead><tr><th>Observation</th><th>Supported conclusion</th><th>Unsupported shortcut</th></tr></thead><tbody><tr><td>Input validation or model registration succeeds</td><td>Those data/assembly checks passed</td><td>The problem was solved</td></tr><tr><td>A mock returns a configured vector</td><td>The solving workflow and result extraction work for this test data</td><td>A native solver found the vector</td></tr><tr><td>An independent enumeration checks a tiny instance</td><td>The enumerated finite instance is checked</td><td>All sizes and continuous models are covered</td></tr><tr><td>Final MILP returns an integer solution</td><td>Inspect business validation and the report</td><td>Global optimality is automatically proved</td></tr><tr><td>The current candidate pool (restricted column pool) is optimal</td><td>That candidate model is optimal</td><td>Missing candidates cannot improve it</td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">Kotlin and Rust API Differences</p><p>Kotlin and Rust share business explanations, while APIs and implemented capabilities can differ. Each lesson identifies its entry points and result semantics; numerical checks apply to that language’s example.</p></div><h2 id="terminology" tabindex="-1">Terminology and Reading Conventions <a class="header-anchor" href="#terminology" aria-label="Permalink to &quot;Terminology and Reading Conventions {#terminology}&quot;">​</a></h2><p>BPP1D uses <strong>container/container type</strong>, BPP2D <strong>sheet/sheet type</strong>, and BPP3D <strong>bin/bin type</strong>. A CSP1D <strong>cutting plan</strong> includes output per execution; a CSP2D <strong>cutting pattern</strong> describes the layout for one execution. API class, field and parameter names remain unchanged.</p><table tabindex="0"><thead><tr><th>Term</th><th>Meaning in these lessons</th></tr></thead><tbody><tr><td>Candidate and column</td><td>A candidate is a selectable loading or cutting combination; a column typically represents one candidate through a variable and its coefficients</td></tr><tr><td>Master problem and restricted master problem (RMP)</td><td>The master chooses candidates and their usages; the restricted master considers only generated candidates, usually starting with a linear relaxation during column generation</td></tr><tr><td>Linear programming (LP) and mixed-integer linear programming (MILP)</td><td>LP allows continuous variables; MILP requires some or all variables to be integer. A linear relaxation temporarily allows fractional values to obtain bounds and guide candidate search</td></tr><tr><td>Column generation and pricing</td><td>Column generation adds candidates in rounds; pricing uses feedback from the master to search for candidates that improve the objective, not to set product prices. Algorithm guarantees depend on the entry point</td></tr><tr><td>Solver backend and adapter</td><td>The backend performs optimization, for example SCIP or Gurobi; an adapter translates framework models, settings and results to the backend interface</td></tr><tr><td>Model registration</td><td>Adding variables, constraints and objectives derived from domain objects to the optimization model</td></tr><tr><td>Heuristic solving</td><td>A rule-based search that generally does not prove full-problem optimality; business validation still applies</td></tr><tr><td>Current feasible solution (incumbent)</td><td>A feasible solution found so far, not necessarily optimal; validate it before business use</td></tr><tr><td>Candidate completeness (<code>complete</code>)</td><td>All candidates under the current rules have been enumerated; this alone does not prove integer optimality</td></tr><tr><td>Objective bound and optimality gap</td><td>Evidence of how far a solution is from the known objective bound; preserve unavailable values as unavailable</td></tr><tr><td>Result metrics (KPI)</td><td>Business statistics such as bin count, utilization, cost and unmet demand; fields vary by framework and language</td></tr></tbody></table>',22)])])}const p=e(i,[["render",r]]);export{m as __pageData,p as default};
